<?php
require_once 'auth_check.php'; require_once __DIR__ . '/app/partials.php'; $conn=getDBConnection();
$byFoundation=$conn->query("SELECT f.fname,COUNT(d.id) donations,COALESCE(SUM(CASE WHEN d.payment_status='Complete' AND d.verified_at IS NOT NULL THEN d.amount END),0) total FROM foundations f LEFT JOIN donations d ON d.foundation_id=f.fid GROUP BY f.fid,f.fname ORDER BY total DESC");
$byMethod=$conn->query("SELECT payment_method,COUNT(*) donations,COALESCE(SUM(CASE WHEN payment_status='Complete' AND verified_at IS NOT NULL THEN amount END),0) total FROM donations GROUP BY payment_method ORDER BY total DESC");
$monthly=$conn->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) donations,COALESCE(SUM(CASE WHEN payment_status='Complete' AND verified_at IS NOT NULL THEN amount END),0) total FROM donations GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month DESC LIMIT 12");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Donation Reports</title><link rel="stylesheet" href="css/addashb.css"><link rel="stylesheet" href="css/admin-workspace.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css"></head><body><div class="dashboard-container"><?php render_admin_sidebar('reports'); ?><main class="workspace-content"><header class="workspace-header"><div><h1>Donation Reports</h1><p>Only verified, completed donations contribute to financial totals.</p></div><a class="button" href="donation_ledger.php">Open ledger</a></header><?php $sets=['By foundation'=>$byFoundation,'By payment method'=>$byMethod,'Monthly donations'=>$monthly]; foreach($sets as $title=>$rows): ?><section class="panel"><h2><?= e($title) ?></h2><div class="table-wrap"><table class="workspace-table"><thead><tr><th>Group</th><th>Donation count</th><th>Completed total (MMK)</th></tr></thead><tbody><?php while($row=$rows->fetch_assoc()): $label=$row['fname']??($row['payment_method']??$row['month']); ?><tr><td><?= e($label) ?></td><td><?= (int)$row['donations'] ?></td><td><?= number_format((float)$row['total'],2) ?></td></tr><?php endwhile; ?></tbody></table></div></section><?php endforeach; ?></main></div></body></html><?php $conn->close(); ?>
